const pages=[['home','Accueil','الرئيسية','⌂','index.html'],['calendar','Calendrier','الجدول','▦','calendar.html'],['standings','Classement','الترتيب','☷','standings.html'],['teams','Équipes','الفرق','♧','teams.html'],['registration','Candidature','التسجيل','＋','registration.html'],['media','Actualités','الأخبار','▤','media.html'],['admin','Administration','الإدارة','⚙','admin.html'],['sponsors','Partenaires','الشركاء','✧','sponsors.html']];
let lang=localStorage.getItem('dfl-lang')||'fr';let current=location.pathname.split('/').pop()||'index.html';let page=pages.find(p=>p[4]===current)||pages[0];
function renderNav(){const publicPages=pages.slice(0,6),orgPages=pages.slice(6);const html=(list,mobile=false)=>list.map(([id,fr,ar,icon,url])=>`<a href="${url}" class="${url===current?'active':''}">${mobile?`<span>${icon}</span>`:`<span class="ico">${icon}</span>`}<span>${lang==='fr'?fr:ar}</span></a>`).join('');const nav=document.getElementById('nav');if(nav)nav.innerHTML=html(publicPages);const org=document.getElementById('orgnav');if(org)org.innerHTML=html(orgPages);const bottom=document.getElementById('bottom');if(bottom)bottom.innerHTML=html(publicPages.slice(0,5),true)}
function translate(){document.documentElement.lang=lang;document.body.classList.toggle('rtl',lang==='ar');document.querySelectorAll('[data-fr][data-ar]').forEach(e=>e.textContent=e.dataset[lang]);const b=document.getElementById('lang');if(b)b.textContent=lang==='fr'?'عربي':'Français';const crumb=document.getElementById('crumb');if(crumb)crumb.textContent=lang==='fr'?page[1]:page[2];const cd=document.getElementById('countdown');if(cd){cd.querySelector('.eyebrow').textContent=lang==='fr'?'OUVERTURE DE LA SAISON':'انطلاق الموسم';cd.querySelector('.countdown-title').textContent=lang==='fr'?'Cérémonie d’ouverture · 03.12.2026':'حفل الافتتاح · 03.12.2026';cd.querySelectorAll('.countbits small').forEach((e,i)=>e.textContent=(lang==='fr'?['jours','heures','min','sec']:['يوم','ساعة','دقيقة','ثانية'])[i])}renderNav();if(document.getElementById('admin-tools')&&!document.getElementById('admin-tools').hidden)renderAdminTools();else if(document.getElementById('admin-gate'))renderGate();renderPublicData()}
const langButton=document.getElementById('lang');if(langButton)langButton.addEventListener('click',()=>{lang=lang==='fr'?'ar':'fr';localStorage.setItem('dfl-lang',lang);translate()});
function setupDisplayControls(){const actions=document.querySelector('.actions');if(!actions)return;const theme=document.createElement('button');theme.className='iconbtn theme-toggle';theme.type='button';theme.title=lang==='fr'?'Changer le thème':'تغيير المظهر';theme.setAttribute('aria-label',theme.title);theme.textContent=localStorage.getItem('dfl-theme')==='dark'?'☀':'◐';actions.insertBefore(theme,actions.querySelector('.avatar'));document.body.classList.toggle('theme-dark',localStorage.getItem('dfl-theme')==='dark');theme.onclick=()=>{const dark=document.body.classList.toggle('theme-dark');localStorage.setItem('dfl-theme',dark?'dark':'light');theme.textContent=dark?'☀':'◐';toast(dark?(lang==='fr'?'Thème sombre activé':'تم تفعيل المظهر الداكن'):(lang==='fr'?'Thème clair activé':'تم تفعيل المظهر الفاتح'))};const clock=document.createElement('span');clock.className='live-clock';clock.setAttribute('aria-live','off');actions.insertBefore(clock,theme);const tick=()=>clock.textContent=new Intl.DateTimeFormat(lang==='fr'?'fr-FR':'ar-TN',{hour:'2-digit',minute:'2-digit'}).format(new Date());tick();setInterval(tick,15000)}
const apply=document.getElementById('apply');if(apply)apply.addEventListener('click',()=>{const inputs=[...document.querySelectorAll('.field input')];const missing=inputs.some(i=>!i.value.trim());if(missing){inputs.find(i=>!i.value.trim())?.focus();toast(lang==='fr'?'Complétez les champs pour continuer.':'يرجى إكمال الحقول للمتابعة.');return}toast(lang==='fr'?'Prototype uniquement : aucune candidature n’a été envoyée.':'نموذج تجريبي فقط: لم يتم إرسال أي طلب.')});
document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');const phase=t.dataset.tab;document.querySelectorAll('#calendar .fixture[data-leg]').forEach(f=>f.hidden=phase!=='all'&&f.dataset.leg!==phase);const msg=document.querySelector('.calendar-filter-note');if(msg)msg.textContent=lang==='fr'?`Filtre sélectionné : ${t.textContent.trim()}.`:`التصفية المحددة: ${t.textContent.trim()}.`}));
function toast(message){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.appendChild(el)}el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function setupCountdown(){const home=document.getElementById('home');if(!home||document.getElementById('countdown'))return;const box=document.createElement('div');box.id='countdown';box.className='countdown card';box.innerHTML=`<div><span class="eyebrow">${lang==='fr'?'OUVERTURE DE LA SAISON':'انطلاق الموسم'}</span><b class="countdown-title">${lang==='fr'?'Cérémonie d’ouverture':'حفل الافتتاح'} · 03.12.2026</b></div><div class="countbits"><span><b data-days>--</b><small>${lang==='fr'?'jours':'يوم'}</small></span><span><b data-hours>--</b><small>${lang==='fr'?'heures':'ساعة'}</small></span><span><b data-minutes>--</b><small>${lang==='fr'?'min':'دقيقة'}</small></span><span><b data-seconds>--</b><small>${lang==='fr'?'sec':'ثانية'}</small></span></div>`;const stats=home.querySelector('.stats');if(stats)stats.before(box);const tick=()=>{const left=new Date('2026-12-03T19:00:00+01:00')-Date.now();const values=left>0?[Math.floor(left/86400000),Math.floor(left/3600000)%24,Math.floor(left/60000)%60,Math.floor(left/1000)%60]:[0,0,0,0];['days','hours','minutes','seconds'].forEach((n,i)=>{const e=box.querySelector(`[data-${n}]`);if(e)e.textContent=String(values[i]).padStart(2,'0')})};tick();setInterval(tick,1000)}
function setupSearch(){const teamGrid=document.querySelector('.teamgrid');if(teamGrid){const input=document.createElement('input');input.className='search team-search';input.placeholder=lang==='fr'?'Rechercher une équipe…':'ابحث عن فريق…';teamGrid.before(input);input.addEventListener('input',()=>teamGrid.querySelectorAll('.teamcard').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(input.value.toLowerCase())))}const fixtures=document.querySelectorAll('.fixture');if(fixtures.length>1&&page[0]==='calendar'){const note=document.createElement('div');note.className='calendar-filter-note';note.textContent=lang==='fr'?'Choisissez une phase pour filtrer le calendrier.':'اختر المرحلة لتصفية الجدول.';document.querySelector('.tabs')?.after(note)}}
const STORE={teams:'dfl-teams',matches:'dfl-matches',code:'dfl-admin-code'};
const read=(key,fallback=[])=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const write=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
function setupAdmin(){const root=document.getElementById('admin');if(!root)return;root.innerHTML=`<div class="page-title"><div class="eyebrow">${lang==='fr'?'ESPACE ORGANISATION':'مساحة التنظيم'}</div><h1>${lang==='fr'?'Administration':'الإدارة'}</h1><p>${lang==='fr'?'Gérez les équipes et les dates de match du prototype.':'إدارة الفرق ومواعيد المباريات في النموذج التجريبي.'}</p></div><div class="demo">ⓘ &nbsp;${lang==='fr'?'Prototype local : code et données enregistrés dans ce navigateur. Ne pas utiliser pour des informations sensibles.':'نموذج محلي: يتم حفظ الرمز والبيانات في هذا المتصفح. لا تستخدم معلومات حساسة.'}</div><div id="admin-gate"></div><div id="admin-tools" hidden></div>`;renderGate()}
function renderGate(){const gate=document.getElementById('admin-gate');if(!gate)return;const hasCode=!!localStorage.getItem(STORE.code),unlocked=sessionStorage.getItem('dfl-admin-unlocked')==='yes';if(unlocked){gate.innerHTML='';renderAdminTools();return}document.getElementById('admin-tools').hidden=true;gate.innerHTML=`<div class="card auth-card"><div class="eyebrow">${hasCode?(lang==='fr'?'ACCÈS ADMIN':'دخول الإدارة'):(lang==='fr'?'PREMIÈRE CONFIGURATION':'الإعداد الأول')}</div><h2>${hasCode?(lang==='fr'?'Entrez votre code admin':'أدخل رمز الإدارة'):(lang==='fr'?'Créez un code admin':'أنشئ رمز الإدارة')}</h2><p>${hasCode?(lang==='fr'?'Utilisez le code défini sur cet appareil.':'استخدم الرمز الذي أنشأته على هذا الجهاز.'):(lang==='fr'?'Choisissez un code pour protéger cet écran sur cet appareil.':'اختر رمزاً لحماية هذه الشاشة على هذا الجهاز.')}</p><form id="gate-form" class="admin-form"><label>${lang==='fr'?'Code admin':'رمز الإدارة'}<input type="password" id="admin-code" required minlength="4" autocomplete="current-password"></label>${hasCode?'':`<label>${lang==='fr'?'Confirmer le code':'تأكيد الرمز'}<input type="password" id="admin-code-confirm" required minlength="4" autocomplete="new-password"></label>`}<button class="primary">${hasCode?(lang==='fr'?'Ouvrir l’administration':'فتح الإدارة'):(lang==='fr'?'Créer le code':'إنشاء الرمز')}</button></form><div id="gate-error" class="form-error" aria-live="polite"></div></div>`;document.getElementById('gate-form').addEventListener('submit',e=>{e.preventDefault();const code=document.getElementById('admin-code').value;if(hasCode){if(code!==localStorage.getItem(STORE.code)){document.getElementById('gate-error').textContent=lang==='fr'?'Code incorrect.':'الرمز غير صحيح.';return}}else{if(code!==document.getElementById('admin-code-confirm').value){document.getElementById('gate-error').textContent=lang==='fr'?'Les codes ne correspondent pas.':'الرمزان غير متطابقين.';return}localStorage.setItem(STORE.code,code)}sessionStorage.setItem('dfl-admin-unlocked','yes');renderGate()})}
function teamOptions(teams){return `<option value="">${lang==='fr'?'Choisir une équipe':'اختر فريقاً'}</option>`+teams.map(t=>`<option value="${escapeHtml(t.id)}">${escapeHtml(t.name)}</option>`).join('')}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function teamName(id){return read(STORE.teams).find(t=>t.id===id)?.name||'—'}
function renderPublicData(){const teams=read(STORE.teams),matches=read(STORE.matches).slice().sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));const grid=document.querySelector('.teamgrid');if(grid)grid.innerHTML=teams.length?teams.map((t,i)=>`<div class="card teamcard"><div class="crest">${['⚽','🌴','☀','✦'][i%4]}</div><h3>${escapeHtml(t.name)}</h3><p>${escapeHtml(t.area||'Djerba')}</p><span class="pill">${lang==='fr'?'Ajoutée':'تمت الإضافة'}</span></div>`).join(''):`<p class="empty-note">${lang==='fr'?'Aucune équipe ajoutée pour le moment.':'لم تتم إضافة فرق بعد.'}</p>`;const calendar=document.getElementById('calendar');if(calendar){const card=calendar.querySelector('.card');if(card)card.innerHTML=matches.length?matches.map(m=>`<div class="fixture" data-leg="${escapeHtml(m.leg)}"><div class="datebox"><b>${escapeHtml(m.date.slice(8,10))}</b>${escapeHtml(m.date.slice(5,7))}</div><div><div class="versusline">${escapeHtml(teamName(m.home))} <span style="color:#94a0ad">vs</span> ${escapeHtml(teamName(m.away))}</div><div class="venue">${escapeHtml(m.round)} · ${escapeHtml(m.venue)} · ${escapeHtml(m.time)}</div></div><span class="pill warn">${lang==='fr'?'Programmé':'مجدول'}</span></div>`).join(''):`<p class="empty-note">${lang==='fr'?'Aucune rencontre enregistrée.':'لا توجد مباريات مسجلة.'}</p>`}if(page[0]==='home'){const stat=document.querySelector('#home .stats .stat strong');if(stat)stat.textContent=teams.length?String(teams.length):'—';const matchCard=[...document.querySelectorAll('#home .card')].find(c=>c.querySelector('.fixture'));if(matchCard&&matches.length){const fixture=matchCard.querySelector('.fixture');const m=matches[0];if(fixture)fixture.innerHTML=`<div class="datebox"><b>${escapeHtml(m.date.slice(8,10))}</b>${escapeHtml(m.date.slice(5,7))}</div><div><div class="versusline">${escapeHtml(teamName(m.home))} <span style="color:#94a0ad">vs</span> ${escapeHtml(teamName(m.away))}</div><div class="venue">${escapeHtml(m.venue)} · ${escapeHtml(m.time)}</div></div><span class="pill warn">${escapeHtml(m.date)}</span>`}}}
function renderAdminTools(){const tools=document.getElementById('admin-tools');if(!tools)return;tools.hidden=false;const teams=read(STORE.teams),matches=read(STORE.matches);tools.innerHTML=`<div class="stats"><div class="stat"><div><label>${lang==='fr'?'Équipes ajoutées':'الفرق المضافة'}</label><strong>${teams.length}</strong></div><div class="staticon">♧</div></div><div class="stat"><div><label>${lang==='fr'?'Dates programmées':'المباريات المجدولة'}</label><strong>${matches.length}</strong></div><div class="staticon">▦</div></div></div><div class="admin-grid"><div class="card"><div class="cardhead"><h2>${lang==='fr'?'Ajouter une équipe':'إضافة فريق'}</h2></div><form id="team-form" class="admin-form"><label>${lang==='fr'?'Nom de l’équipe':'اسم الفريق'}<input name="name" required maxlength="50" placeholder="Ex. Club de Djerba"></label><label>${lang==='fr'?'Ville / secteur':'المدينة / المنطقة'}<input name="area" maxlength="50" placeholder="Djerba"></label><button class="primary">${lang==='fr'?'Ajouter l’équipe':'إضافة الفريق'}</button></form><div class="admin-list" id="team-list"></div></div><div class="card"><div class="cardhead"><h2>${lang==='fr'?'Programmer un match':'جدولة مباراة'}</h2></div><form id="match-form" class="admin-form"><label>${lang==='fr'?'Équipe à domicile':'الفريق المضيف'}<select name="home" required>${teamOptions(teams)}</select></label><label>${lang==='fr'?'Équipe visiteuse':'الفريق الضيف'}<select name="away" required>${teamOptions(teams)}</select></label><div class="form-row"><label>${lang==='fr'?'Date':'التاريخ'}<input name="date" type="date" required></label><label>${lang==='fr'?'Heure':'الوقت'}<input name="time" type="time" required></label></div><label>${lang==='fr'?'Stade':'الملعب'}<input name="venue" required maxlength="70" placeholder="${lang==='fr'?'Stade municipal':'الملعب البلدي'}"></label><label>${lang==='fr'?'Journée':'الجولة'}<input name="round" type="number" min="1" max="30" value="1" required></label><label>${lang==='fr'?'Phase':'المرحلة'}<select name="leg"><option value="first">${lang==='fr'?'Aller':'ذهاب'}</option><option value="return">${lang==='fr'?'Retour':'إياب'}</option></select></label><button id="match-submit" type="submit" class="primary" ${teams.length<2?'disabled':''}>${lang==='fr'?'Enregistrer le match':'حفظ المباراة'}</button></form><div class="admin-list" id="match-list"></div></div></div><div class="admin-actions"><button id="admin-logout" class="tab">${lang==='fr'?'Verrouiller l’administration':'قفل الإدارة'}</button><button id="reset-data" class="tab danger">${lang==='fr'?'Effacer les données locales':'مسح البيانات المحلية'}</button></div>`;
const teamList=document.getElementById('team-list');teamList.innerHTML=teams.length?`<h3>${lang==='fr'?'Équipes enregistrées':'الفرق المسجلة'}</h3>`+teams.map(t=>`<div class="saved-row"><span><b>${escapeHtml(t.name)}</b><small>${escapeHtml(t.area||'')}</small></span><button class="remove-btn" data-remove-team="${escapeHtml(t.id)}">×</button></div>`).join(''):`<p class="empty-note">${lang==='fr'?'Aucune équipe ajoutée.':'لم تتم إضافة فرق.'}</p>`;
const matchList=document.getElementById('match-list');matchList.innerHTML=matches.length?`<h3>${lang==='fr'?'Matchs programmés':'المباريات المجدولة'}</h3>`+matches.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(m=>`<div class="saved-row"><span><b>${escapeHtml(teamName(m.home))} – ${escapeHtml(teamName(m.away))}</b><small>${escapeHtml(m.date)} · ${escapeHtml(m.time)} · ${escapeHtml(m.venue)}</small></span><div class="row-actions"><button class="edit-btn" data-edit-match="${escapeHtml(m.id)}">${lang==='fr'?'Modifier':'تعديل'}</button><button class="remove-btn" data-remove-match="${escapeHtml(m.id)}" aria-label="${lang==='fr'?'Supprimer':'حذف'}">×</button></div></div>`).join(''):`<p class="empty-note">${lang==='fr'?'Aucun match programmé.':'لم تتم جدولة مباريات.'}</p>`;
document.getElementById('team-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget),name=String(data.get('name')).trim(),area=String(data.get('area')).trim();if(teams.some(t=>t.name.toLowerCase()===name.toLowerCase())){toast(lang==='fr'?'Cette équipe existe déjà.':'هذا الفريق موجود بالفعل.');return}teams.push({id:crypto.randomUUID(),name,area});write(STORE.teams,teams);renderAdminTools();renderPublicData();toast(lang==='fr'?'Équipe ajoutée.':'تمت إضافة الفريق.')});
document.getElementById('match-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,d=Object.fromEntries(new FormData(form)),editing=form.dataset.editing;if(d.home===d.away){toast(lang==='fr'?'Choisissez deux équipes différentes.':'اختر فريقين مختلفين.');return}if(matches.some(m=>m.id!==editing&&m.date===d.date&&m.time===d.time&&(m.home===d.home||m.away===d.home||m.home===d.away||m.away===d.away))){toast(lang==='fr'?'Conflit : une équipe a déjà un match à cette date et heure.':'تعارض: لدى أحد الفريقين مباراة في هذا التاريخ والوقت.');return}if(editing){const index=matches.findIndex(m=>m.id===editing);if(index>=0)matches[index]={id:editing,...d}}else matches.push({id:crypto.randomUUID(),...d});write(STORE.matches,matches);renderAdminTools();renderPublicData();toast(lang==='fr'?(editing?'Match modifié.':'Match programmé dans ce prototype.'):(editing?'تم تعديل المباراة.':'تمت جدولة المباراة في النموذج.'))});
document.querySelectorAll('[data-remove-team]').forEach(b=>b.onclick=()=>{const id=b.dataset.removeTeam;if(read(STORE.matches).some(m=>m.home===id||m.away===id)){toast(lang==='fr'?'Supprimez d’abord les matchs de cette équipe.':'احذف مباريات هذا الفريق أولاً.');return}write(STORE.teams,read(STORE.teams).filter(t=>t.id!==id));renderAdminTools();renderPublicData()});document.querySelectorAll('[data-remove-match]').forEach(b=>b.onclick=()=>{write(STORE.matches,read(STORE.matches).filter(m=>m.id!==b.dataset.removeMatch));renderAdminTools();renderPublicData()});document.querySelectorAll('[data-edit-match]').forEach(b=>b.onclick=()=>{const m=read(STORE.matches).find(x=>x.id===b.dataset.editMatch);if(!m)return;const form=document.getElementById('match-form');Object.entries(m).forEach(([k,v])=>{if(form.elements[k])form.elements[k].value=v});form.dataset.editing=m.id;const submit=form.querySelector('#match-submit');if(submit)submit.textContent=lang==='fr'?'Enregistrer les modifications':'حفظ التعديلات';form.scrollIntoView({behavior:'smooth',block:'center'});toast(lang==='fr'?'Modifiez les champs puis enregistrez.':'عدّل الحقول ثم احفظ.')});document.getElementById('admin-logout').onclick=()=>{sessionStorage.removeItem('dfl-admin-unlocked');renderGate()};document.getElementById('reset-data').onclick=()=>{if(confirm(lang==='fr'?'Effacer toutes les équipes et tous les matchs de ce navigateur ?':'هل تريد مسح جميع الفرق والمباريات من هذا المتصفح؟')){localStorage.removeItem(STORE.teams);localStorage.removeItem(STORE.matches);renderAdminTools();renderPublicData()}}}
function setupMotion(){document.body.dataset.page=page[0];const progress=document.createElement('div');progress.className='scroll-progress';document.body.appendChild(progress);let frame=0;const updateProgress=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?scrollY/max:0})`})};window.addEventListener('scroll',updateProgress,{passive:true});updateProgress();const canvas=document.createElement('canvas');canvas.id='ambient-canvas';canvas.setAttribute('aria-hidden','true');document.body.prepend(canvas);const ctx=canvas.getContext('2d');const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(ctx&&!reduce){let w=0,h=0,particles=[];const resize=()=>{const dpr=Math.min(devicePixelRatio||1,1.5);w=innerWidth;h=innerHeight;canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);particles=Array.from({length:Math.min(38,Math.floor(w/34))},()=>({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.5+.4,vx:(Math.random()-.5)*.18,vy:-Math.random()*.22-.04,a:Math.random()*.34+.12}))};resize();window.addEventListener('resize',resize,{passive:true});const draw=()=>{ctx.clearRect(0,0,w,h);for(const p of particles){p.x+=p.vx;p.y+=p.vy;if(p.y<-4){p.y=h+4;p.x=Math.random()*w}if(p.x<-4)p.x=w+4;if(p.x>w+4)p.x=-4;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle=`rgba(215,173,84,${p.a})`;ctx.fill()}requestAnimationFrame(draw)};draw()}document.querySelectorAll('.card,.stat,.teamcard').forEach(card=>{card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect();card.style.setProperty('--pointer-x',`${e.clientX-r.left}px`);card.style.setProperty('--pointer-y',`${e.clientY-r.top}px`)});card.addEventListener('pointerleave',()=>{card.style.removeProperty('--pointer-x');card.style.removeProperty('--pointer-y')})});document.querySelectorAll('.primary,.iconbtn,.lang,.tab').forEach(button=>button.addEventListener('click',e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=button.getBoundingClientRect(),dot=document.createElement('i');dot.className='ripple';dot.style.left=`${e.clientX-r.left}px`;dot.style.top=`${e.clientY-r.top}px`;button.appendChild(dot);dot.addEventListener('animationend',()=>dot.remove(),{once:true})}));if('IntersectionObserver'in window){const countObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;const node=e.target,target=Number(node.dataset.countTarget);if(!Number.isFinite(target)){countObserver.unobserve(node);return}const start=performance.now(),duration=850;const run=now=>{const p=Math.min(1,(now-start)/duration),ease=1-Math.pow(1-p,3);node.textContent=Math.round(target*ease).toLocaleString(lang==='fr'?'fr-FR':'ar-TN');if(p<1)requestAnimationFrame(run)};requestAnimationFrame(run);countObserver.unobserve(node)}),{threshold:.7});document.querySelectorAll('.stat strong').forEach(n=>{const target=Number(n.textContent.replace(/\D/g,''));if(Number.isFinite(target)&&target>0){n.dataset.countTarget=String(target);countObserver.observe(n)}})}}
function reveal(){document.querySelectorAll('.card,.stat,.page-title,.demo,.teamcard').forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--delay',`${Math.min(i%6,5)*70}ms`)});if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}else document.querySelectorAll('.reveal').forEach(el=>el.classList.add('in'))}
translate();setupDisplayControls();setupAdmin();renderPublicData();setupCountdown();setupSearch();reveal();setupMotion();
window.addEventListener('storage',event=>{if(event.key===STORE.teams||event.key===STORE.matches){renderPublicData();if(sessionStorage.getItem('dfl-admin-unlocked')==='yes')renderAdminTools()}if(event.key===STORE.code&&document.getElementById('admin'))renderGate()});




